SELECT 'asics-superblast-3-vs-asics-novablast-6',(SELECT id FROM running_shoes WHERE slug='asics-superblast-3'),(SELECT id FROM running_shoes WHERE slug='asics-novablast-6'),'popular',(SELECT brand || ' ' || model FROM running_shoes WHERE slug='asics-superblast-3') || ' vs ' || (SELECT brand || ' ' || model FROM running_shoes WHERE slug='asics-novablast-6'),'Compare source-linked specifications, recorded US prices and intended use.','No overall winner: choose for fit and intended use.',NULL,'Specifications are not a wear test. Check source dates and availability.','[]',json_object('shoe1',(SELECT replace(category,'_',' ') FROM running_shoes WHERE slug='asics-superblast-3'),'shoe2',(SELECT replace(category,'_',' ') FROM running_shoes WHERE slug='asics-novablast-6')) WHERE true ON CONFLICT(slug) DO UPDATE SET comparison_type=excluded.comparison_type,title=excluded.title,meta_description=excluded.meta_description,verdict=excluded.verdict,verdict_winner=NULL,verdict_reason=excluded.verdict_reason,key_differences=excluded.key_differences,best_for=excluded.best_for;
